def patch_config_to_dict(config, *, inference_only: bool = False) -> dict:
    """Return PatchConfig values as a JSON-native dictionary.

    ``config`` may be a PatchConfig-like object or a mapping. Missing fields in
    historical mappings receive the current PatchConfig defaults. Set
    ``inference_only=True`` to omit training-only sampling, queue, and data-state
    settings.
    """
    if isinstance(config, Mapping):
        source = config
        value = lambda key, default: source.get(key, default)
    else:
        value = lambda key, default: getattr(config, key, default)
    fields = _PATCH_INFERENCE_FIELDS if inference_only else _PATCH_CONFIG_DEFAULTS
    return {
        key: _to_jsonable(value(key, _PATCH_CONFIG_DEFAULTS[key]))
        for key in fields
    }


def make_output_spec(kind: str, *, threshold: float = None, classes=None,
                     output_shape=None, class_axis: int = 1) -> dict:
    """Build a versioned, allow-listed inference output/decoding contract.

    Supported ``kind`` values are ``binary_segmentation``,
    ``multiclass_segmentation``, ``classification``, and ``regression``.
    """
    spec = {'output_schema': '1', 'kind': kind}
    if kind == 'binary_segmentation':
        threshold = 0.5 if threshold is None else float(threshold)
        if not 0 <= threshold <= 1:
            raise ValueError("binary segmentation threshold must be in [0, 1]")
        spec.update(activation='sigmoid', decision='threshold',
                    threshold=threshold, class_axis=int(class_axis))
    elif kind == 'multiclass_segmentation':
        if classes is None:
            raise ValueError("multiclass_segmentation requires classes")
        if isinstance(classes, int):
            if classes < 2:
                raise ValueError("multiclass segmentation requires at least two classes")
            classes = list(range(classes))
        if not isinstance(classes, (list, tuple)) or len(classes) < 2:
            raise ValueError("classes must be an integer or an ordered sequence")
        spec.update(activation='softmax', decision='argmax',
                    classes=_to_jsonable(classes), class_axis=int(class_axis))
    elif kind == 'classification':
        if not isinstance(classes, (list, tuple)) or not classes:
            raise ValueError("classification requires a non-empty ordered class vocabulary")
        spec.update(activation='softmax', decision='argmax',
                    classes=_to_jsonable(classes), class_axis=int(class_axis))
    elif kind == 'regression':
        if isinstance(output_shape, int):
            output_shape = [output_shape]
        if not isinstance(output_shape, (list, tuple)) or not output_shape:
            raise ValueError("regression requires output_shape")
        spec.update(activation='identity', decision='identity',
                    output_shape=_to_jsonable(output_shape))
    else:
        raise ValueError(f"Unsupported output kind {kind!r}")
    return spec


def _validate_output_spec(spec: Mapping) -> dict:
    if not isinstance(spec, Mapping):
        raise TypeError("output_spec must be a mapping made by make_output_spec")
    expected = make_output_spec(
        spec.get('kind'), threshold=spec.get('threshold'), classes=spec.get('classes'),
        output_shape=spec.get('output_shape'), class_axis=spec.get('class_axis', 1))
    if dict(spec) != expected:
        raise ValueError("output_spec is incomplete or contains unsupported fields")
    return expected


def patch_inference_config(config, output_spec: Mapping) -> dict:
    """Build the complete versioned inference contract for a patch workflow."""
    return {
        'config_schema': '1',
        'workflow': 'patch',
        'patch_config': patch_config_to_dict(config, inference_only=True),
        'output': _validate_output_spec(output_spec),
    }


def standard_inference_config(apply_reorder: bool, target_spacing, item_tfms: list,
                              output_spec: Mapping) -> dict:
    """Build a complete standard/whole-volume inference contract from transform specs."""
    config = {
        'config_schema': '1',
        'workflow': 'standard',
        'apply_reorder': apply_reorder,
        'target_spacing': _to_jsonable(target_spacing),
        'item_tfms': _to_jsonable(item_tfms),
        'output': _validate_output_spec(output_spec),
    }
    return _validate_inference_config(config)


def decode_model_output(logits: torch.Tensor, output_spec: Mapping):
    """Apply the declared safe output contract to raw model logits."""
    spec = _validate_output_spec(output_spec)
    kind = spec['kind']
    if kind == 'binary_segmentation':
        return (torch.sigmoid(logits) >= spec['threshold']).long()
    if kind == 'multiclass_segmentation':
        if logits.shape[spec['class_axis']] != len(spec['classes']):
            raise ValueError("logit class dimension does not match output_spec classes")
        return torch.softmax(logits, dim=spec['class_axis']).argmax(dim=spec['class_axis'])
    if kind == 'classification':
        if logits.shape[spec['class_axis']] != len(spec['classes']):
            raise ValueError("logit class dimension does not match output_spec classes")
        indices = torch.softmax(logits, dim=spec['class_axis']).argmax(dim=spec['class_axis'])
        classes = spec['classes']
        flat = [classes[index] for index in indices.detach().cpu().reshape(-1).tolist()]
        return flat[0] if indices.numel() == 1 else flat
    if kind == 'regression':
        if list(logits.shape[1:]) != spec['output_shape']:
            raise ValueError(
                f"Regression logits shape {list(logits.shape[1:])} != {spec['output_shape']}")
        return logits
    raise ValueError(f"Unsupported output kind {kind!r}")

