# %% ../nbs/07_utils.ipynb #compilehelpers
def unwrap_compiled_model(model):
    """Return `model` with any torch.compile wrapper removed.

    `torch.compile(model)` returns an `OptimizedModule` that holds the original
    module as `_orig_mod` alongside TorchDynamo state bound to the torch build that
    created it. A learner exported while compiled loads on any torch, but raises on
    the first forward pass under a different one. The returned module shares its
    weights with the wrapper.

    Args:
        model: An nn.Module, or a fastai Learner whose `.model` is unwrapped in place.

    Returns:
        The innermost nn.Module, or the same Learner that was passed in. A model that
        was never compiled is returned unchanged.

    Note:
        Handles `torch.compile(model)`. `model.compile()` compiles in place and leaves
        no wrapper to remove.
    """
    if isinstance(model, Learner):
        model.model = unwrap_compiled_model(model.model)
        return model

    while hasattr(model, '_orig_mod'):
        model = model._orig_mod
    return model


def strip_compile_prefix(state_dict, prefix: str = '_orig_mod.'):
    """Remove the torch.compile key prefix from a state dict, in place.

    `learn.save()` on a compiled model writes keys prefixed with `_orig_mod.`, which
    an uncompiled module cannot load.

    Args:
        state_dict: A state dict, e.g. from `torch.load`. fastai checkpoints written
            with `with_opt=True` are {'model': ..., 'opt': ...}; pass the 'model' value.
        prefix: Key prefix to remove.

    Returns:
        The same dict, so it can be passed straight to `load_state_dict`. A dict
        without the prefix is returned unchanged.
    """
    from torch.nn.modules.utils import consume_prefix_in_state_dict_if_present

    consume_prefix_in_state_dict_if_present(state_dict, prefix)
    return state_dict


MODEL_ARTIFACT_SCHEMA = '1'
_MODEL_CONSTRUCTORS = {}
_MODEL_WRAPPERS = {}


def register_model_constructor(arch_id: str, constructor: Callable, *, replace: bool = False):
    """Register a trusted model constructor for Safetensors reconstruction."""
    if not isinstance(arch_id, str) or not arch_id:
        raise ValueError("arch_id must be a non-empty string")
    if not callable(constructor):
        raise TypeError("constructor must be callable")
    if arch_id in _MODEL_CONSTRUCTORS and not replace:
        raise ValueError(f"Model constructor {arch_id!r} is already registered")
    _MODEL_CONSTRUCTORS[arch_id] = constructor


def register_model_wrapper(wrapper_id: str, constructor: Callable, *, replace: bool = False):
    """Register a trusted ``constructor(model, **kwargs)`` wrapper."""
    if not isinstance(wrapper_id, str) or not wrapper_id:
        raise ValueError("wrapper_id must be a non-empty string")
    if not callable(constructor):
        raise TypeError("constructor must be callable")
    if wrapper_id in _MODEL_WRAPPERS and not replace:
        raise ValueError(f"Model wrapper {wrapper_id!r} is already registered")
    _MODEL_WRAPPERS[wrapper_id] = constructor


def _json_round_trip(value, name: str):
    try:
        return json.loads(json.dumps(_to_jsonable(value), sort_keys=True,
                                     separators=(',', ':'), allow_nan=False))
    except (TypeError, ValueError) as e:
        raise ValueError(f"{name} must be JSON serializable: {e}") from e


def make_model_spec(arch_id: str, arch_kwargs: Mapping, wrapper_spec=None) -> dict:
    """Create a validated, versioned model specification.

    Wrappers are listed from inner to outer and use
    ``{'wrapper_id': str, 'wrapper_kwargs': dict}``.
    """
    if arch_id not in _MODEL_CONSTRUCTORS:
        raise ValueError(f"Unknown model architecture {arch_id!r}")
    if not isinstance(arch_kwargs, Mapping):
        raise TypeError("arch_kwargs must be a mapping")
    wrappers = [] if wrapper_spec is None else wrapper_spec
    if isinstance(wrappers, Mapping):
        wrappers = [wrappers]
    if not isinstance(wrappers, (list, tuple)):
        raise TypeError("wrapper_spec must be a mapping or ordered sequence")
    normalized_wrappers = []
    for wrapper in wrappers:
        if not isinstance(wrapper, Mapping) or set(wrapper) != {'wrapper_id', 'wrapper_kwargs'}:
            raise ValueError("Each wrapper requires exactly wrapper_id and wrapper_kwargs")
        wrapper_id = wrapper['wrapper_id']
        if wrapper_id not in _MODEL_WRAPPERS:
            raise ValueError(f"Unknown model wrapper {wrapper_id!r}")
        if not isinstance(wrapper['wrapper_kwargs'], Mapping):
            raise TypeError("wrapper_kwargs must be a mapping")
        normalized_wrappers.append({
            'wrapper_id': wrapper_id,
            'wrapper_kwargs': _json_round_trip(wrapper['wrapper_kwargs'], 'wrapper_kwargs'),
        })
    return {
        'artifact_schema': MODEL_ARTIFACT_SCHEMA,
        'arch_id': arch_id,
        'arch_kwargs': _json_round_trip(arch_kwargs, 'arch_kwargs'),
        'wrapper_spec': normalized_wrappers,
    }


def _validate_model_spec(spec: Mapping) -> dict:
    if not isinstance(spec, Mapping):
        raise TypeError("model_spec must be a mapping made by make_model_spec")
    if set(spec) != {'artifact_schema', 'arch_id', 'arch_kwargs', 'wrapper_spec'}:
        raise ValueError("model_spec is incomplete or contains unsupported fields")
    if str(spec['artifact_schema']) != MODEL_ARTIFACT_SCHEMA:
        raise ValueError(f"Unsupported model artifact schema {spec['artifact_schema']!r}")
    normalized = make_model_spec(spec['arch_id'], spec['arch_kwargs'], spec['wrapper_spec'])
    if dict(spec) != normalized:
        raise ValueError("model_spec is not canonical")
    return normalized


def build_model_from_spec(spec: Mapping):
    """Rebuild a model only through registered, trusted constructors and wrappers."""
    spec = _validate_model_spec(spec)
    model = _MODEL_CONSTRUCTORS[spec['arch_id']](**spec['arch_kwargs'])
    for wrapper in spec['wrapper_spec']:
        model = _MODEL_WRAPPERS[wrapper['wrapper_id']](model, **wrapper['wrapper_kwargs'])
    return model


def _validate_inference_config(config: Mapping) -> dict:
    if not isinstance(config, Mapping):
        raise TypeError("inference_config must be a mapping")
    config = _json_round_trip(config, 'inference_config')
    if config.get('config_schema') != '1':
        raise ValueError("inference_config requires config_schema='1'")
    _validate_output_spec(config.get('output'))
    workflow = config.get('workflow')
    if workflow == 'patch':
        if set(config) != {'config_schema', 'workflow', 'patch_config', 'output'}:
            raise ValueError("Patch inference_config is incomplete or has unsupported fields")
        patch_config = config.get('patch_config')
        if (
            not isinstance(patch_config, Mapping)
            or set(patch_config) != set(_PATCH_INFERENCE_FIELDS)
        ):
            raise ValueError(
                "Patch inference_config must contain exactly the inference PatchConfig fields"
            )
    elif workflow == 'standard':
        expected = {'config_schema', 'workflow', 'apply_reorder', 'target_spacing',
                    'item_tfms', 'output'}
        if set(config) != expected or not isinstance(config['item_tfms'], list):
            raise ValueError("Standard inference_config is incomplete or has unsupported fields")
        if not isinstance(config['apply_reorder'], bool):
            raise TypeError("standard apply_reorder must be bool")
        try:
            from fastMONAI.vision_augmentation import transforms_from_specs
            transforms_from_specs(config['item_tfms'])
        except Exception as e:
            raise ValueError(f"Invalid or unsupported standard item_tfms: {e}") from e
    else:
        raise ValueError(f"Unsupported inference workflow {workflow!r}")
    return config


def read_safetensors_metadata(path: str | Path) -> dict:
    """Read and validate parsed fastMONAI Safetensors metadata."""
    from safetensors import safe_open

    with safe_open(str(path), framework='pt', device='cpu') as handle:
        raw = handle.metadata() or {}
    required = {'artifact_schema', 'arch_id', 'arch_kwargs', 'wrapper_spec', 'repr',
                'inference_config', 'artifact_role', 'mlflow_run'}
    missing = required - set(raw)
    if missing:
        raise ValueError(f"Safetensors metadata is missing {sorted(missing)}")
    try:
        spec = {
            'artifact_schema': raw['artifact_schema'],
            'arch_id': raw['arch_id'],
            'arch_kwargs': json.loads(raw['arch_kwargs']),
            'wrapper_spec': json.loads(raw['wrapper_spec']),
        }
        spec = _validate_model_spec(spec)
        inference_config = _validate_inference_config(json.loads(raw['inference_config']))
    except (json.JSONDecodeError, TypeError, ValueError) as e:
        raise ValueError(f"Invalid Safetensors metadata in {path}: {e}") from e
    if raw['artifact_role'] not in {'final', 'best'}:
        raise ValueError(f"Invalid artifact_role {raw['artifact_role']!r}")
    parsed = dict(raw)
    parsed.update(spec)
    parsed['repr'] = raw['repr']
    parsed['inference_config'] = inference_config
    return parsed


def save_safetensors_model(model, path: str | Path, model_spec: Mapping,
                           inference_config: Mapping, artifact_role: str,
                           mlflow_run: str = None, *, extra_metadata: Mapping = None) -> Path:
    """Save a rebuildable nn.Module with the model-level Safetensors API."""
    from safetensors.torch import save_model

    spec = _validate_model_spec(model_spec)
    inference_config = _validate_inference_config(inference_config)
    if artifact_role not in {'final', 'best'}:
        raise ValueError("artifact_role must be 'final' or 'best'")
    model = unwrap_compiled_model(model)
    rebuilt = build_model_from_spec(spec)
    if repr(rebuilt) != repr(model):
        raise ValueError("model_spec rebuild does not match repr(model); refusing to save")
    if mlflow_run is None:
        active_run = mlflow.active_run()
        mlflow_run = active_run.info.run_id if active_run is not None else ''
    metadata = {
        'artifact_schema': MODEL_ARTIFACT_SCHEMA,
        'arch_id': spec['arch_id'],
        'arch_kwargs': json.dumps(spec['arch_kwargs'], sort_keys=True, separators=(',', ':')),
        'wrapper_spec': json.dumps(spec['wrapper_spec'], sort_keys=True, separators=(',', ':')),
        'repr': repr(model),
        'inference_config': json.dumps(inference_config, sort_keys=True, separators=(',', ':')),
        'artifact_role': artifact_role,
        'mlflow_run': str(mlflow_run),
    }
    if extra_metadata:
        overlap = set(extra_metadata) & set(metadata)
        if overlap:
            raise ValueError(f"extra_metadata cannot replace reserved keys {sorted(overlap)}")
        metadata.update({str(key): str(value) for key, value in extra_metadata.items()})
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    save_model(model, str(path), metadata=metadata)
    return path


def load_safetensors_model(path: str | Path, device='cpu'):
    """Strict-load a registered Safetensors model and return it in eval mode."""
    from safetensors.torch import load_model

    metadata = read_safetensors_metadata(path)
    spec = {key: metadata[key] for key in
            ('artifact_schema', 'arch_id', 'arch_kwargs', 'wrapper_spec')}
    model = build_model_from_spec(spec)
    if repr(model) != metadata['repr']:
        raise ValueError("Rebuilt model repr differs from the artifact metadata")
    load_model(model, str(path), strict=True, device=str(device))
    return model.to(device).eval()


def load_model_artifact(path: str | Path, device='cpu'):
    """Load a Safetensors model artifact."""
    path = Path(path)
    if path.suffix != '.safetensors':
        raise ValueError("Model artifacts must use the '.safetensors' extension")
    return load_safetensors_model(path, device=device)


def _normalize_monai_kwargs(kwargs):
    kwargs = dict(kwargs)
    tuple_keys = {'channels', 'strides', 'kernel_size', 'upsample_kernel_size', 'filters'}
    pair_keys = {'act', 'norm', 'dropout'}
    for key in tuple_keys:
        if isinstance(kwargs.get(key), list):
            kwargs[key] = tuple(kwargs[key])
    for key in pair_keys:
        if isinstance(kwargs.get(key), list) and len(kwargs[key]) == 2:
            kwargs[key] = (kwargs[key][0], kwargs[key][1])
    return kwargs


def _monai_constructor(name, *, inner=False):
    def build(**kwargs):
        from monai.networks import nets
        model = getattr(nets, name)(**_normalize_monai_kwargs(kwargs))
        return model.model if inner else model
    return build


def _dynunet_ds_wrapper(model, **kwargs):
    if kwargs:
        raise ValueError("DynUNetDSAdapter has no wrapper kwargs")
    from fastMONAI.vision_loss import DynUNetDSAdapter
    return DynUNetDSAdapter(model)


def _segmamba_constructor(**kwargs):
    try:
        from models_segmamba.segmambav2 import SegMamba
    except ImportError as e:
        raise ImportError("segmamba.v2 requires the supported SegMamba-V2 fork") from e
    return SegMamba(**kwargs)


_MODEL_CONSTRUCTORS.update({
    'monai.unet': _monai_constructor('UNet'),
    'monai.unet_inner': _monai_constructor('UNet', inner=True),
    'monai.dynunet': _monai_constructor('DynUNet'),
    'monai.classifier': _monai_constructor('Classifier'),
    'monai.regressor': _monai_constructor('Regressor'),
    'segmamba.v2': _segmamba_constructor,
})
_MODEL_WRAPPERS['fastmonai.dynunet_ds_adapter'] = _dynunet_ds_wrapper

