def _detect_patch_workflow(dls) -> bool:
    """Detect if DataLoaders are patch-based (MedPatchDataLoaders).
    
    Args:
        dls: DataLoaders instance
        
    Returns:
        True if dls is a MedPatchDataLoaders instance
    """
    return hasattr(dls, 'patch_config') or hasattr(dls, '_patch_config')


def _extract_size_from_transforms(tfms) -> list | None:
    """Extract target size from PadOrCrop transform if present.
    
    Args:
        tfms: List of transforms
        
    Returns:
        Target size as list, or None if not found
    """
    if tfms is None:
        return None
    for tfm in tfms:
        if hasattr(tfm, 'pad_or_crop') and hasattr(tfm.pad_or_crop, 'target_shape'):
            return list(tfm.pad_or_crop.target_shape)
    return None


def _extract_standard_config(learn) -> dict:
    """Extract config from standard MedDataBlock workflow.
    
    Args:
        learn: fastai Learner instance
        
    Returns:
        Dictionary with extracted configuration
    """
    from fastMONAI.vision_core import MedBase
    dls = learn.dls

    apply_reorder = MedBase.apply_reorder
    target_spacing = MedBase.target_spacing

    # Extract item_tfms from DataLoaders pipeline
    item_tfms = []
    if hasattr(dls, 'after_item') and dls.after_item:
        item_tfms = list(dls.after_item.fs)

    size = _extract_size_from_transforms(item_tfms)

    return {
        'apply_reorder': apply_reorder,
        'target_spacing': target_spacing,
        'size': size,
        'item_tfms': item_tfms,
        'batch_size': dls.bs,
        'patch_config': None,
    }


def _extract_patch_config(learn) -> dict:
    """Extract config from MedPatchDataLoaders workflow.
    
    Args:
        learn: fastai Learner instance
        
    Returns:
        Dictionary with extracted configuration including patch-specific params
    """
    dls = learn.dls
    patch_config = getattr(dls, '_patch_config', None) or getattr(dls, 'patch_config', None)

    config = {
        'apply_reorder': getattr(dls, '_apply_reorder', patch_config.apply_reorder if patch_config else False),
        'target_spacing': getattr(dls, '_target_spacing', patch_config.target_spacing if patch_config else None),
        'size': patch_config.patch_size if patch_config else None,
        'item_tfms': getattr(dls, '_pre_patch_tfms', []) or [],
        'batch_size': dls.bs,
    }

    # Add patch-specific params for logging
    if patch_config:
        config['patch_config'] = patch_config_to_dict(patch_config)
    else:
        config['patch_config'] = None

    return config


def _extract_loss_name(learn) -> str:
    """Extract loss function name from Learner.
    
    Args:
        learn: fastai Learner instance
        
    Returns:
        Name of the loss function
    """
    loss_func = learn.loss_func
    # Handle CustomLoss wrapper
    if hasattr(loss_func, 'loss_func'):
        inner = loss_func.loss_func
        return inner._get_name() if hasattr(inner, '_get_name') else inner.__class__.__name__
    return loss_func._get_name() if hasattr(loss_func, '_get_name') else loss_func.__class__.__name__


def _extract_model_name(learn) -> str:
    """Extract model architecture name from Learner.
    
    Args:
        learn: fastai Learner instance
        
    Returns:
        Name of the model architecture
    """
    # nn.Module._get_name resolves on the class, so an OptimizedModule reports itself
    # rather than proxying through to the module it wraps.
    model = unwrap_compiled_model(learn.model)
    return model._get_name() if hasattr(model, '_get_name') else model.__class__.__name__

def _canonical_tracking_json(value):
    return json.dumps(
        value, sort_keys=True, separators=(',', ':'), ensure_ascii=True, allow_nan=False
    )


def _split_items_frame(items, is_valid):
    """Copy the rows selected by fastai for one side of a split."""
    if isinstance(items, pd.DataFrame):
        frame = items.copy()
    elif isinstance(items, pd.Series):
        frame = items.to_frame()
    else:
        try:
            values = list(items)
        except TypeError as error:
            raise ValueError(
                'Could not inspect the DataLoaders split items. Pass log_split=False '
                'to opt out, or expose train_ds.items and valid_ds.items.'
            ) from error
        frame = pd.DataFrame({'sample_id': [str(value) for value in values]})
    frame['is_valid'] = bool(is_valid)
    return frame


def _actual_split_df(dls):
    """Return actual train/valid membership after fastai has applied its splitter."""
    try:
        split_df = dls.split_df
    except (AttributeError, TypeError):
        split_df = None
    if split_df is not None:
        frame = split_df.copy()
        if not isinstance(frame, pd.DataFrame) or 'is_valid' not in frame.columns:
            raise ValueError('dls.split_df must be a DataFrame containing is_valid')
        return frame

    train_ds = getattr(dls, 'train_ds', None)
    valid_ds = getattr(dls, 'valid_ds', None)
    train_items = getattr(train_ds, 'items', None)
    valid_items = getattr(valid_ds, 'items', None)
    if train_items is None or valid_items is None:
        raise ValueError(
            'Could not determine actual train/validation membership from the '
            'DataLoaders. Pass log_split=False to opt out.'
        )
    return pd.concat([
        _split_items_frame(train_items, False),
        _split_items_frame(valid_items, True),
    ], ignore_index=True)


def _resolve_column(frame, value):
    if value is None:
        return None
    if isinstance(value, (list, tuple)):
        value = value[0] if value else None
    if value is None:
        return None
    if isinstance(value, int):
        if value < 0 or value >= len(frame.columns):
            return None
        return frame.columns[value]
    return value if value in frame.columns else None


def _split_identity_column(dls, frame, sample_id_col=None):
    """Choose an identity, preferring the raw image path over a cache path."""
    if sample_id_col is not None:
        column = _resolve_column(frame, sample_id_col)
        if column is None:
            raise ValueError(
                f"sample_id_col {sample_id_col!r} is not present in the actual split"
            )
        return column

    column = _resolve_column(frame, getattr(dls, '_img_col', None))
    if isinstance(column, str) and column.endswith('_preprocessed'):
        raw_column = column[:-len('_preprocessed')]
        if raw_column in frame.columns:
            column = raw_column
    if column is not None:
        return column
    if 'sample_id' in frame.columns:
        return 'sample_id'

    candidates = [
        name for name in frame.columns
        if name != 'is_valid' and isinstance(name, str)
        and (name == 'path' or name.endswith('_path'))
    ]
    if len(candidates) == 1:
        return candidates[0]
    raise ValueError(
        'Could not choose a stable sample identity for split_version. '
        'Pass sample_id_col to create_mlflow_callback().'
    )


def _split_version(dls, sample_id_col=None):
    """Hash only actual sample identity and train/valid membership."""
    frame = _actual_split_df(dls)
    identity_col = _split_identity_column(dls, frame, sample_id_col)
    if frame[identity_col].isna().any():
        raise ValueError(f'Split identity column {identity_col!r} contains missing values')

    audit = frame.copy()
    audit['sample_id'] = audit[identity_col].map(str)
    audit['is_valid'] = audit['is_valid'].map(bool)
    records = audit[['sample_id', 'is_valid']].to_dict(orient='records')
    records.sort(key=lambda row: (row['sample_id'], row['is_valid']))
    version = hashlib.sha256(
        _canonical_tracking_json(records).encode('utf-8')
    ).hexdigest()
    return version, audit, identity_col


def _read_preprocessing_manifest(path, dataset_version=None):
    """Validate a manifest and return its cache/dataset identities."""
    manifest_path = Path(path).expanduser().resolve(strict=True)
    try:
        manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
    except json.JSONDecodeError as error:
        raise ValueError(f'Invalid preprocessing manifest JSON: {manifest_path}') from error
    if not isinstance(manifest, dict) or manifest.get('manifest_schema') != 1:
        raise ValueError('Unsupported preprocessing manifest schema')

    cache_version = manifest.get('preprocessing_cache_version')
    version_payload = {
        key: manifest.get(key)
        for key in ('manifest_schema', 'dataset_version', 'contract', 'sources')
    }
    expected = hashlib.sha256(
        _canonical_tracking_json(version_payload).encode('utf-8')
    ).hexdigest()
    if not isinstance(cache_version, str) or cache_version != expected:
        raise ValueError('preprocessing_cache_version does not match manifest contents')
    manifest_dataset_version = manifest.get('dataset_version')
    if (
        dataset_version is not None
        and dataset_version != manifest_dataset_version
    ):
        raise ValueError(
            'dataset_version does not match the preprocessing manifest'
        )
    return manifest_path, cache_version, (
        dataset_version if dataset_version is not None else manifest_dataset_version
    )


