def _download_model_artifact(run_id, artifact_role):
    artifact_path = f"model/{artifact_role}_model.safetensors"
    artifacts = mlflow.artifacts.list_artifacts(
        run_id=run_id, artifact_path="model")
    available = {artifact.path for artifact in artifacts if not artifact.is_dir}
    if artifact_path not in available:
        return None
    return mlflow.artifacts.download_artifacts(
        run_id=run_id, artifact_path=artifact_path)


def _validate_expected_members(out, expected_members):
    if expected_members is None:
        return
    if isinstance(expected_members, int):
        if len(out) != expected_members:
            raise ValueError(
                f"Expected {expected_members} model artifacts, found {len(out)}: {list(out)}")
        return
    expected = list(expected_members)
    missing = [member for member in expected if member not in out]
    extra = [member for member in out if member not in expected]
    if missing or extra:
        raise ValueError(f"Model member mismatch: missing={missing}, extra={extra}")


def find_model_artifacts(*, run_ids, artifact_role, expected_members=None):
    """Download explicitly selected Safetensors model artifacts from MLflow.

    ``run_ids`` must map each stable member identifier to one immutable MLflow
    run ID. Experiment-name or latest-run discovery is intentionally unsupported:
    callers must declare exactly which trained models inference will use.
    """
    if artifact_role not in {'best', 'final'}:
        raise ValueError("artifact_role must be 'best' or 'final'")
    if not isinstance(run_ids, Mapping):
        raise TypeError("run_ids must be a mapping of member IDs to MLflow run IDs")
    if not run_ids:
        raise ValueError("run_ids must not be empty")

    selected = list(run_ids.items())
    invalid = [run_id for _, run_id in selected
               if not isinstance(run_id, str) or not run_id.strip()]
    if invalid:
        raise ValueError("Every MLflow run ID must be a non-empty string")
    values = [run_id for _, run_id in selected]
    if len(values) != len(set(values)):
        raise ValueError("run_ids mapping contains duplicate run IDs")
    _validate_expected_members(run_ids, expected_members)
    _ensure_fastmonai_tracking_uri()

    out = {}
    for member, run_id in selected:
        path = _download_model_artifact(run_id, artifact_role)
        if path is None:
            raise FileNotFoundError(
                f"No {artifact_role} Safetensors artifact in declared run {run_id!r}")
        out[member] = path
    return out

