import subprocess
import threading
import time
import socket
import os
import sys
import atexit
import signal
import ctypes
from IPython.display import display, HTML
import shutil

# Ask the OS to SIGTERM the `mlflow ui` child the instant this (parent) process dies;
# this covers a hard-killed kernel (SIGKILL/OOM), which atexit cannot. Linux-only;
# a no-op elsewhere. libc is loaded once here, outside any fork, so the preexec_fn hook
# below stays minimal (preexec_fn is documented as unsafe in multithreaded programs, and
# we launch mlflow ui from a daemon thread, so keeping the hook tiny is the accepted pattern).
_libc = None
if sys.platform.startswith('linux'):
    try:
        _libc = ctypes.CDLL('libc.so.6', use_errno=True)
    except OSError:
        _libc = None


def _die_with_parent():
    """preexec hook: runs in the child after fork(), before exec(). Sets Linux PR_SET_PDEATHSIG."""
    if _libc is not None:
        _libc.prctl(1, signal.SIGTERM)  # PR_SET_PDEATHSIG = 1


class MLflowUIManager:
    """Launch and manage a local ``mlflow ui`` server from a notebook.

    The UI's lifetime is tied to the kernel: it is reaped when the interpreter
    exits, gracefully (via an atexit handler) or on a hard kill (via Linux
    PR_SET_PDEATHSIG, see ``_die_with_parent``), so closing/restarting the
    notebook never leaves an orphaned server holding the port. Call ``stop()``
    to shut it down sooner. An externally-started UI is reused, not killed.
    """

    def __init__(self):
        self.process = None
        self.thread = None
        self.port = 5001
        self.host = '0.0.0.0'
        self.backend_store_uri = _resolve_backend_store_uri()
        self._owns_process = False
        self._reusing_external = False
        # Reap the mlflow ui subprocess on clean interpreter shutdown (graceful kernel
        # shutdown/restart runs atexit). PR_SET_PDEATHSIG covers hard kills.
        atexit.register(self._kill_process)
        
    def is_port_available(self, port):
        """Check if a port is available."""
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            try:
                s.bind(('localhost', port))
                return True
            except OSError:
                return False
    
    def is_mlflow_running(self):
        """Check if MLflow UI is actually responding."""
        import requests
        try:
            response = requests.get(f'http://localhost:{self.port}', timeout=2)
            return response.status_code == 200
        except (requests.RequestException, ConnectionError, OSError):
            return False
    
    def _find_running_mlflow(self):
        """Find an existing MLflow UI in our port range. Returns port or None."""
        import requests
        for port in range(self.port, self.port + 10):
            if not self.is_port_available(port):
                try:
                    response = requests.get(f'http://localhost:{port}', timeout=2)
                    if response.status_code == 200 and 'mlflow' in response.text.lower():
                        return port
                except (requests.RequestException, ConnectionError, OSError):
                    continue
        return None
    
    def find_available_port(self, start_port=5001):
        """Find an available port starting from start_port."""
        for port in range(start_port, start_port + 10):
            if self.is_port_available(port):
                return port
        return None
    
    def check_mlflow_installed(self):
        """Check if MLflow is installed."""
        return shutil.which('mlflow') is not None
    
    def start_ui(self, auto_open=True, quiet=False):
        """Start MLflow UI with better error handling and user feedback."""
        # Refresh in case the tracking URI was configured after __init__
        self.backend_store_uri = _resolve_backend_store_uri()
        
        if not self.check_mlflow_installed():
            if not quiet:
                display(HTML('<div style="color: #d32f2f; font-weight: bold; font-size: 14px;">MLflow not installed. Run: pip install mlflow</div>'))
            return False
        
        existing_port = self._find_running_mlflow()
        if existing_port is not None:
            self.port = existing_port
            self._owns_process = False
            self._reusing_external = True
            if not quiet:
                display(HTML(f'''
                    <div style="background-color: #e3f2fd; border: 2px solid #1976d2; padding: 15px; border-radius: 8px; margin: 10px 0;">
                        <div style="color: #0d47a1; font-weight: bold; font-size: 16px; margin-bottom: 10px;">
                            Reusing existing MLflow UI on port {self.port}
                        </div>
                        <a href="http://localhost:{self.port}" target="_blank" 
                           style="background-color: #1976d2; color: white; padding: 12px 24px; text-decoration: none; border-radius: 6px; font-weight: bold; font-size: 14px; display: inline-block; margin: 5px 0;">
                            Open MLflow UI
                        </a>
                        <div style="margin-top: 10px;">
                            <div style="color: #424242; font-size: 13px;">URL: http://localhost:{self.port}</div>
                        </div>
                    </div>
                '''))
            else:
                display(HTML(f'''
                    <a href="http://localhost:{self.port}" target="_blank" 
                       style="color: #1976d2; font-weight: bold; font-size: 16px; text-decoration: underline;">
                       MLflow UI (Port {self.port}, reused)
                    </a>
                '''))
            return True
        
        available_port = self.find_available_port(self.port)
        if available_port is None:
            if not quiet:
                display(HTML('<div style="color: #d32f2f; font-weight: bold; font-size: 14px;">No available ports found (5001-5010)</div>'))
            return False
        
        self.port = available_port
        
        def run_mlflow():
            try:
                self.process = subprocess.Popen([
                    'mlflow', 'ui', 
                    '--host', self.host,
                    '--port', str(self.port),
                    '--backend-store-uri', self.backend_store_uri
                ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                   preexec_fn=_die_with_parent if _libc is not None else None)
                self.process.wait()
            except Exception as e:
                if not quiet:
                    display(HTML(f'<div style="color: #d32f2f; font-weight: bold; font-size: 14px;">Error: {str(e)}</div>'))
        
        self.thread = threading.Thread(target=run_mlflow, daemon=True)
        self.thread.start()
        
        max_wait = 10
        for i in range(max_wait):
            time.sleep(1)
            if self.is_mlflow_running():
                self._owns_process = True
                self._reusing_external = False
                if quiet:
                    display(HTML(f'''
                        <a href="http://localhost:{self.port}" target="_blank" 
                           style="color: #1976d2; font-weight: bold; font-size: 16px; text-decoration: underline;">
                           MLflow UI (Port {self.port})
                        </a>
                    '''))
                else:
                    display(HTML(f'''
                        <div style="background-color: #c8e6c9; border: 2px solid #388e3c; padding: 15px; border-radius: 8px; margin: 10px 0;">
                            <div style="color: #1b5e20; font-weight: bold; font-size: 16px; margin-bottom: 10px;">
                                MLflow UI is running successfully!
                            </div>
                            <a href="http://localhost:{self.port}" target="_blank" 
                               style="background-color: #1976d2; color: white; padding: 12px 24px; text-decoration: none; border-radius: 6px; font-weight: bold; font-size: 14px; display: inline-block; margin: 5px 0;">
                                Open MLflow UI
                            </a>
                            <div style="margin-top: 10px;">
                                <div style="color: #424242; font-size: 13px;">URL: http://localhost:{self.port}</div>
                            </div>
                        </div>
                    '''))
                return True
        
        if not quiet:
            display(HTML('<div style="color: #d32f2f; font-weight: bold; font-size: 14px;">Failed to start MLflow UI</div>'))
        return False

    def _kill_process(self):
        """Terminate the mlflow ui subprocess: terminate -> wait(timeout) -> kill.

        Quiet (no IPython display) so it is safe to run during interpreter shutdown,
        and idempotent. Used by both ``stop()`` and the atexit handler. Only acts on a
        process this manager started (``_owns_process``); never an externally-started UI.
        """
        proc = self.process
        if proc is None or not self._owns_process:
            return
        self.process, self._owns_process = None, False
        try:
            proc.terminate()
            try:
                proc.wait(timeout=5)
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait(timeout=5)
        except Exception:
            pass

    def stop(self):
        """Stop the MLflow UI server (terminate -> wait -> kill)."""
        if self.process and self._owns_process:
            self._kill_process()
            display(HTML('''
                <div style="background-color: #ffecb3; border: 2px solid #f57c00; padding: 10px; border-radius: 6px;">
                    <span style="color: #e65100; font-weight: bold; font-size: 14px;">MLflow UI stopped</span>
                </div>
            '''))
        elif self._reusing_external:
            self._reusing_external = False
            display(HTML('''
                <div style="background-color: #e3f2fd; border: 2px solid #1976d2; padding: 10px; border-radius: 6px;">
                    <span style="color: #0d47a1; font-weight: bold; font-size: 14px;">MLflow UI was started externally, not stopping it</span>
                </div>
            '''))
        else:
            display(HTML('''
                <div style="background-color: #f0f0f0; border: 2px solid #757575; padding: 10px; border-radius: 6px;">
                    <span style="color: #424242; font-weight: bold; font-size: 14px;">MLflow UI is not currently running</span>
                </div>
            '''))
    
    def status(self):
        """Check MLflow UI status."""
        if self.is_mlflow_running():
            display(HTML(f'''
                <div style="background-color: #c8e6c9; border: 2px solid #388e3c; padding: 10px; border-radius: 6px;">
                    <div style="color: #1b5e20; font-weight: bold; font-size: 14px;">MLflow UI is running</div>
                    <a href="http://localhost:{self.port}" target="_blank" 
                       style="color: #1976d2; font-weight: bold; text-decoration: underline;">
                       http://localhost:{self.port}
                    </a>
                </div>
            '''))
        else:
            display(HTML('''
                <div style="background-color: #ffcdd2; border: 2px solid #d32f2f; padding: 10px; border-radius: 6px;">
                    <div style="color: #b71c1c; font-weight: bold; font-size: 14px;">MLflow UI is not running</div>
                    <div style="color: #424242; font-size: 13px; margin-top: 5px;">
                        Run <code style="background-color: #f5f5f5; padding: 2px 4px; border-radius: 3px;">mlflow_ui.start_ui()</code> to start it.
                    </div>
                </div>
            '''))
